import RNA, random, time
target='.....((((.(...(.((((.(.((((.((.((((.((.(((....))).).)))))).).))))....).)))).)...).))))....................'
n=len(target)
stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[i]=j; pairs[j]=i
paired_idx=[i for i in pairs]
unpaired=[i for i in range(n) if i not in pairs]
def pairs_of(ss):
    st=[]; p={}
    for i,c in enumerate(ss):
        if c=='(': st.append(i)
        elif c==')':
            j=st.pop(); p[i]=j; p[j]=i
    return p
pt=pairs_of(target)
def score(seq):
    s,_=RNA.fold(seq)
    if s==target: return 0
    return RNA.bp_distance(s,target)
def diagnose(seq):
    s,_=RNA.fold(seq)
    ps=pairs_of(s)
    missing=[(i,pt[i]) for i in pt if i<pt[i] and (i not in ps or ps[i]!=pt[i])]
    spurious=[(i,ps[i]) for i in ps if i<ps[i] and (i not in pt or pt[i]!=ps[i])]
    return missing,spurious

seed='UUAAACAGAACGGCGCUAGCUCGGGAUAGGCCUGGACGUGCGUUUCCGCCCAGCCAGCACAAUCCAGGGGAGCUACCAAAGAUCUGCUCGACACACGCACACUUUC'
best=list(seed); bs=score(seed)
print("start",bs,flush=True)
print(diagnose(''.join(best)),flush=True)
random.seed(11)
t0=time.time()
for it in range(30000):
    cand=list(best)
    r=random.random()
    if r<0.7 and paired_idx:
        i=random.choice(paired_idx); j=pairs[i]
        a,b=random.choice([('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')])
        cand[i]=a; cand[j]=b
    elif unpaired:
        i=random.choice(unpaired); cand[i]=random.choice('ACGU')
    cs=score(''.join(cand))
    if cs<=bs and (cs<bs or random.random()<0.1):
        best=cand; bs=cs
    if bs==0:
        print("SOLVED",it,flush=True); break
